sp_widget.client_script:
function($scope, spUtil, spModal) {

		$scope.goBack = function () {
				window.history.back();
		};

		$scope.activeTab = "all";

		$scope.setTab = function(tab){
				$scope.activeTab = tab;
		};

		$scope.showApproval = function(approval){

				if($scope.activeTab === "all")
						return true;

				return approval.type === $scope.activeTab;
		};

    $scope.approve = function(approval) {

        $scope.data.action = "approve";
        $scope.data.sys_id = approval.sys_id;

        spUtil.update($scope).then(function() {
            delete $scope.data.action;
            delete $scope.data.sys_id;
        });

    };

		$scope.openRecord = function(approval) {
				window.open(approval.url, "_blank");
		};

    $scope.reject = function(approval) {

        spModal.prompt("Please enter rejection comments").then(function(comment) {

            if (!comment)
                return;

            $scope.data.action = "reject";
            $scope.data.sys_id = approval.sys_id;
            $scope.data.comments = comment;

            spUtil.update($scope).then(function() {
                delete $scope.data.action;
                delete $scope.data.sys_id;
                delete $scope.data.comments;
            });

        });

    };

    $scope.nextPage = function() {
        $scope.data.pagination.currentPage++;
        spUtil.update($scope);
    };

    $scope.previousPage = function() {
        if ($scope.data.pagination.currentPage > 0)
            $scope.data.pagination.currentPage--;

        spUtil.update($scope);
    };

}

sp_widget.css:
.panel-title {
    font-weight: 600;
}

.qb-page-topbar {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 15px;
}

.qb-back-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #ffffff;
    border: 1.5px solid #e2e8f0;
    cursor: pointer;
    color: #374151;
    flex-shrink: 0;
    transition: background .15s, border-color .15s;
}

.qb-back-btn:hover {
    background: #f1f5f9;
    border-color: #94a3b8;
}

.panel-title {
    flex: 1;
    margin: 0;
    font-weight: 600;
}

.approval-tabs{
    display:flex;
    gap:10px;
    margin:15px 0 20px;
    border-bottom:1px solid #ececec;
    padding-bottom:12px;
}

.approval-tabs button{
    background:#f5f5f5;
    border:1px solid #ddd;
    padding:8px 18px;
    border-radius:25px;
    font-weight:600;
    cursor:pointer;
    transition:.2s;
}

.approval-tabs button:hover{
    background:#e9ecef;
}

.approval-tabs button.active{
    background:#000;
    color:#fff;
    border-color:#000;
}

.approval-card {
    background: #fff;
    border: 1px solid #dcdcdc;
    border-radius: 8px;
    margin-bottom: 20px;
    transition: all .2s ease;
}

.approval-card:hover {
    box-shadow: 0 3px 10px rgba(0,0,0,.08);
}

.approval-header{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:18px;
}

.approval-title{
    font-size:18px;
    font-weight:600;
    color:#2f7edb;
}

.btn-view{
    background:#fff;
    color:#000000;
    border:.1rem solid #bfbbbb;
    border-radius:8px;
    padding:6px 14px;
    font-weight:600;
    transition:.2s;
}

.btn-view:hover{
    background:#000000;
    color:#fff;
}

.btn-view i{
    margin-right:6px;
}

.approval-employee {
    font-size: 15px;
    color: #666;
    margin-top: 4px;
}

.approval-details {
    margin-top: 15px;
}

.approval-row {
    display: flex;
    margin-bottom: 10px;
}

.approval-label {
    width: 130px;
    font-weight: 600;
    color: #555;
}

.approval-value {
    flex: 1;
    color: #222;
}

.approval-actions {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
    margin-top: 25px;
    padding-top: 20px;
    border-top: 1px solid #e5e5e5;
}

.approval-actions .btn {
    min-width: 120px;
    height: 42px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    transition: all .2s ease;
}

.btn-reject {
    background: #fde8e8;
    color: #d92d20;
    border: none;
}

.btn-reject:hover {
    background: #fbd5d5;
}

.btn-approve {
    background: #000;
    color: #fff;
    border: none;
}

.btn-approve:hover {
    background: #222;
}

.label {
    font-size: 1.4rem;
  	color: black;
  	padding: 0;
}

.label-warning {
    background: #f0ad4e;
}

.label-success {
    background: #5cb85c;
}

.label-danger {
    background: #d9534f;
}

.empty-state {
    text-align: center;
    color: #777;
    padding: 40px 20px;
}

.empty-state i {
    font-size: 40px;
    margin-bottom: 15px;
    color: #ccc;
}

.pagination-footer {
    padding: 15px;
    overflow: hidden;
}

.pagination-footer .btn {
    min-width: 100px;
}

@media (max-width: 768px) {

    .approval-row {
        display: block;
    }

    .approval-label {
        width: auto;
        margin-bottom: 4px;
    }

    .approval-actions {
        text-align: center;
    }

    .approval-actions .btn {
        width: 100%;
        margin: 6px 0;
    }

}

sp_widget.script:
(function () {

    // -------------------------------
    // Configuration
    // -------------------------------
    var PAGE_SIZE = parseInt(options.max_number_of_elements_shown_on_the_list, 10) || 10;

    data.approvals = [];
		data.quotaCount = 0;
		data.planCount = 0;
		data.statementCount = 0;
		data.participantCount = 0;
    data.ids = [];
    data.showApprovals = true;

    // -------------------------------
    // Pagination
    // -------------------------------
    var currentPage = 0;
    var start = 0;
    var end = PAGE_SIZE;

    if (input && input.pagination) {
        currentPage = parseInt(input.pagination.currentPage, 10) || 0;
        start = currentPage * PAGE_SIZE;
        end = start + PAGE_SIZE;
    }

    // -------------------------------
    // Approve / Reject
    // -------------------------------
    if (input && input.action) {

        var approvalGR = new GlideRecordSecure("sysapproval_approver");

        if (approvalGR.get(input.sys_id)) {

            // Ensure current user is the approver
            if (approvalGR.getValue("approver") == gs.getUserID()) {

                if (input.action == "approve") {

                    approvalGR.setValue("state", "approved");
                    approvalGR.update();

                } else if (input.action == "reject") {

                    approvalGR.setValue("state", "rejected");

                    if (input.comments)
                        approvalGR.comments = input.comments;

                    approvalGR.update();
                }
            }
        }
    }

    // -------------------------------
    // Fetch Pending Approvals
    // -------------------------------

		// Get total count
		var ga = new GlideAggregate("sysapproval_approver");
		ga.addQuery("approver", gs.getUserID());
		ga.addQuery("state", "requested");
		ga.addAggregate("COUNT");
		ga.query();

		var total = 0;
		if (ga.next()) {
				total = parseInt(ga.getAggregate("COUNT"), 10);
		}

    var approval = new GlideRecordSecure("sysapproval_approver");

    approval.addQuery("approver", gs.getUserID());
    approval.addQuery("state", "requested");
    approval.orderByDesc("sys_created_on");
    approval.chooseWindow(start, end);
    approval.query();


    while (approval.next()) {

        var target = null;

        if (!approval.sysapproval.nil())
            target = approval.sysapproval.getRefRecord();
        else
            target = approval.document_id.getRefRecord();

        if (!target || !target.isValidRecord())
            continue;

        var row = {};

				row.url = "";

				switch (target.getTableName()) {

						case "x_ctans_incentnow_quota":
								row.url = "?id=quota_builder&table=x_ctans_incentnow_quota&sys_id=" +
													target.getUniqueValue() +
													"&approval_id=" + approval.getUniqueValue();
								break;

						case "x_ctans_incentnow_plan":
								row.url = "?id=create_plan&table=x_ctans_incentnow_plan&sys_id=" +
													target.getUniqueValue() +
													"&approval_id=" + approval.getUniqueValue();
								break;

						case "x_ctans_incentnow_incentive_statement":
								row.url = "?id=incentive_statement_view&statement_id=" +
													target.getUniqueValue() +
													"&approval_id=" + approval.getUniqueValue();
								break;

						case "x_ctans_incentnow_participant_assignment":
								row.url = "?id=YOUR_PARTICIPANT_PAGE" +
										"&table=x_ctans_incentnow_participant_assignment" +
										"&sys_id=" + target.getUniqueValue() +
										"&approval_id=" + approval.getUniqueValue();
								break;

						default:
								row.url = "";
				}

        row.sys_id = approval.getUniqueValue();

        row.state = approval.getValue("state");
        row.stateLabel = approval.state.getDisplayValue();

        row.table = target.getTableName();
        row.tableLabel = target.getLabel();

				switch (row.table) {

				case "x_ctans_incentnow_quota":
						row.type = "quota";
						data.quotaCount++;
						break;

				case "x_ctans_incentnow_plan":
						row.type = "plan";
						data.planCount++;
						break;

				case "x_ctans_incentnow_incentive_statement":
						row.type = "statement";
						data.statementCount++;
						break;

				case "x_ctans_incentnow_participant_assignment":
						row.type = "participant";
						data.participantCount++;
						break;

				default:
						row.type = "other";
		}

        row.record_sys_id = target.getUniqueValue();

        // Number
        if (target.isValidField("number"))
            row.number = target.getDisplayValue("number");
        else
            row.number = target.getDisplayValue();

        // Title
        row.title = "";

        if (target.isValidField("name"))
            row.title = target.getDisplayValue("name");

        else if (target.isValidField("short_description"))
            row.title = target.getDisplayValue("short_description");

        // Employee / User
        row.employee = "";

        if (target.isValidField("employee"))
            row.employee = target.employee.getDisplayValue();

        else if (target.isValidField("user"))
            row.employee = target.user.getDisplayValue();

        else if (target.isValidField("requested_for"))
            row.employee = target.requested_for.getDisplayValue();

        // Requested By
        row.requested_by = "";

        if (target.isValidField("requested_by"))
            row.requested_by = target.requested_by.getDisplayValue();

        else if (target.isValidField("opened_by"))
            row.requested_by = target.opened_by.getDisplayValue();

        else if (target.isValidField("sys_created_by"))
            row.requested_by = target.getDisplayValue("sys_created_by");

        // Created Date
        row.created = approval.getDisplayValue("sys_created_on");

        // Display Table Name
        var td = new GlideRecordSecure(target.getTableName());

        if (td.isValid())
            row.table_display = td.getLabel();
        else
            row.table_display = target.getTableName();

        data.ids.push(row.sys_id);
        data.approvals.push(row);
    }

    // -------------------------------
    // Pagination Object
    // -------------------------------
    data.pagination = {};

    data.pagination.currentPage = currentPage;

    data.pagination.from = total === 0 ? 0 : start + 1;

    data.pagination.to = start + data.approvals.length;

    data.pagination.of = total;

    data.pagination.hasPrevious = currentPage > 0;

    data.pagination.hasNext = end < total;

    data.pagination.showPagination =
        data.pagination.hasPrevious ||
        data.pagination.hasNext;

})();
